css:
body {
 background: #333;
}
 #loader-1 {
  display: inline-flex;
  gap: 5px;
  animation: l1-0 1s infinite;
}
#loader-1:before,
#loader-1:after {
  content: "";
  width: 25px;
  aspect-ratio: 1;
  box-shadow: 0 0 0 3px inset #fff;
  transform-origin: top right;
  animation: l1-1 1s infinite;
}
#loader-1:after {
  transform-origin: top left;
  --s: -1;
}
@keyframes l1-0 {
  to {transform: translateY(100%)}
}
@keyframes l1-1 {
  to {transform: rotate(calc(var(--s, 1) * 90deg))}
}
